/**
 * 町名地段溢價（已控制屋齡、盡量控制房型）。
 * premiumPercent 為「該町成交㎡單價 ÷ 同區同條件中位數 − 1」。
 * grain 為 "layout_age" 表示在同房型同屋齡帶內比較，"age" 表示跨房型只控屋齡。
 */
export interface MlitTownPremiumRow {
  region: string;
  district: string;
  /** 町名，例如「西新宿」。 */
  town: string;
  premiumPercent: number;
  cellCount: number;
  sampleCount: number;
  grain: "layout_age" | "age";
}

